query FormatsByMemberId($memberId: Int!, $withMember: Boolean!, $withAlias: Boolean!, $aliasId: Int!) {
  alias(id: $aliasId) @include(if: $withAlias) {
    id
    formats
    league {
      id
      slug
      isDefault
      __typename
    }
    __typename
  }
  member(id: $memberId) @include(if: $withMember) {
    id
    ... on Member {
      aliases {
        id
        formats
        league {
          id
          slug
          isDefault
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
